SELECT

FROM t_order
WHERE user_id = #{userId,jdbcType=BIGINT}
  AND isDelete = 0

    AND order_no = #{orderNo,jdbcType=VARCHAR}


    AND status = #{status,jdbcType=TINYINT}


    AND goods_name LIKE CONCAT('%', #{goodsName,jdbcType=VARCHAR}, '%')

ORDER BY create_time DESC

SELECT o.id, o.user_id, o.goods_id, o.shop_id, o.order_no, o.goods_price, o.buyGoods_num, o.total_amount, o.goods_name, o.goods_img, o.sku_id, o.user_address_id, o.status, o.mobile, o.receiver, o.province, o.city, o.area, o.detail_address, o.pay_time, o.delivery_time, o.receive_time, o.expire_time, o.isDelete, o.create_time, o.update_time FROM t_order o INNER JOIN t_goods g ON o.goods_id = g.id WHERE g.user_id = #{merchantUserId,jdbcType=BIGINT} AND o.isDelete = 0 AND g.isDelete = 0
AND o.order_no = #{orderNo,jdbcType=VARCHAR}
AND o.status = #{status,jdbcType=TINYINT}
AND o.goods_name LIKE CONCAT('%', #{goodsName,jdbcType=VARCHAR}, '%')
ORDER BY o.create_time DESC

