UPDATE t_order
user_id = #{userId,jdbcType=BIGINT}, goods_id = #{goodsId,jdbcType=BIGINT}, shop_id = #{shopId,jdbcType=BIGINT}, order_no = #{orderNo,jdbcType=VARCHAR}, goods_price = #{goodsPrice,jdbcType=DECIMAL}, buyGoods_num = #{buyGoodsNum,jdbcType=INTEGER}, total_amount = #{totalAmount,jdbcType=DECIMAL}, goods_name = #{goodsName,jdbcType=VARCHAR}, goods_img = #{goodsImg,jdbcType=VARCHAR}, sku_id = #{skuId,jdbcType=BIGINT}, user_address_id = #{userAddressId,jdbcType=BIGINT}, status = #{status,jdbcType=TINYINT}, mobile = #{mobile,jdbcType=VARCHAR}, receiver = #{receiver,jdbcType=VARCHAR}, province = #{province,jdbcType=VARCHAR}, city = #{city,jdbcType=VARCHAR}, area = #{area,jdbcType=VARCHAR}, detail_address = #{detailAddress,jdbcType=VARCHAR}, pay_time = #{payTime,jdbcType=TIMESTAMP}, delivery_time = #{deliveryTime,jdbcType=TIMESTAMP}, receive_time = #{receiveTime,jdbcType=TIMESTAMP}, expire_time = #{expireTime,jdbcType=TIMESTAMP}, isDelete = #{isDelete,jdbcType=TINYINT}, update_time = #{updateTime,jdbcType=TIMESTAMP},
WHERE id = #{id,jdbcType=BIGINT}
